package io.github.rebrowser.browser;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.ByteBuffer;
import java.util.*;

/** Product policy tests, independent of Android/Gecko runtime or real website data. */
public final class HistoryRetentionTest {
 static String id(String prefix,int value){return prefix+String.format(Locale.ROOT,"%032x",value);}
 static HistoryStore.Source source(int n,BrowserModels.Level level,boolean open){return new HistoryStore.Source(id("ws_",n),"来源"+n,level,open);}
 static HistoryStore.Page page(int ws,int tab,BrowserModels.Level level,String url){return new HistoryStore.Page(source(ws,level,true),id("tab_",tab),"标题"+tab,url);}
 static HistoryStore.Snapshot empty(){return new HistoryStore.Snapshot(0,false,Collections.emptyList());}
 static final BrowserModels.Level TEMP=BrowserModels.Level.TEMPORARY,SECOND=BrowserModels.Level.SECONDARY,PRIMARY=BrowserModels.Level.PRIMARY;
 static HistoryStore.Snapshot visit(HistoryStore.Snapshot s,int ws,int tab,BrowserModels.Level level,long now){return s.addObservedVisit(page(ws,tab,level,"https://example.test/"+tab),now);}
 @Test public void ordinaryTemporaryWorkspaceRecordsHistoryForThirtyMinutes(){HistoryStore.Snapshot s=visit(empty(),1,1,TEMP,100);assertEquals(Long.valueOf(100+HistoryStore.RETENTION_MS),s.entries().get(0).expiresUtcMs());assertNotNull(s.findVisible(s.entries().get(0).id(),100+HistoryStore.RETENTION_MS-1));assertNull(s.findVisible(s.entries().get(0).id(),100+HistoryStore.RETENTION_MS));}
 @Test public void openSecondaryAndPrimaryDoNotExpire(){for(BrowserModels.Level level:Arrays.asList(SECOND,PRIMARY)){HistoryStore.Snapshot s=visit(empty(),1,1,level,10);assertFalse(s.entries().get(0).timed());assertEquals(1,s.expire(Long.MAX_VALUE).entries().size());}}
 @Test public void closingWholeSecondaryStartsDeadlineAtClosingNotVisit(){HistoryStore.Snapshot s=visit(empty(),1,1,SECOND,10).workspaceChanged(source(1,SECOND,false),200);assertEquals(Long.valueOf(200+HistoryStore.RETENTION_MS),s.entries().get(0).expiresUtcMs());}
 @Test public void temporaryCloseAndRepeatedShelfNeverRenewTimedEntries(){HistoryStore.Snapshot s=visit(empty(),1,1,TEMP,10);Long original=s.entries().get(0).expiresUtcMs();s=s.workspaceChanged(source(1,TEMP,false),100).workspaceChanged(source(1,TEMP,false),200);assertEquals(original,s.entries().get(0).expiresUtcMs());HistoryStore.Snapshot shelved=visit(empty(),1,1,SECOND,1).workspaceChanged(source(1,SECOND,false),10);assertEquals(shelved.entries().get(0).expiresUtcMs(),shelved.workspaceChanged(source(1,SECOND,false),50).entries().get(0).expiresUtcMs());}
 @Test public void promotionChangesAllTabsOnlyInThatWorkspace(){HistoryStore.Snapshot s=visit(visit(visit(empty(),1,1,TEMP,1),1,2,TEMP,2),2,3,TEMP,3).workspaceChanged(source(1,SECOND,true),20);for(HistoryStore.Entry e:s.entries())assertEquals(e.workspaceId().equals(id("ws_",2)),e.timed());}
 @Test public void demotionAddsOneTransitionDeadlineToOldRecordsButNewVisitsUseOwnTime(){HistoryStore.Snapshot s=visit(empty(),1,1,SECOND,10).workspaceChanged(source(1,TEMP,true),100);s=visit(s,1,2,TEMP,200);assertEquals(Long.valueOf(200+HistoryStore.RETENTION_MS),s.entries().get(0).expiresUtcMs());assertEquals(Long.valueOf(100+HistoryStore.RETENTION_MS),s.entries().get(1).expiresUtcMs());}
 @Test public void restoringExpiredSourceCannotResurrectDeletedHistory(){HistoryStore.Snapshot s=visit(empty(),1,1,SECOND,1).workspaceChanged(source(1,SECOND,false),10);assertEquals(0,s.workspaceChanged(source(1,SECOND,true),10+HistoryStore.RETENTION_MS).entries().size());}
 @Test public void restoringLiveSecondaryMakesItsHistoryLongLivedAgain(){HistoryStore.Snapshot s=visit(empty(),1,1,SECOND,1).workspaceChanged(source(1,SECOND,false),10).workspaceChanged(source(1,SECOND,true),20);assertNull(s.entries().get(0).expiresUtcMs());}
 @Test public void maintainingStopsExpiryNotRecordingAndBlocksTimedClear(){HistoryStore.Snapshot s=visit(empty(),1,1,TEMP,1).withMaintaining(true,10);s=visit(s,1,2,TEMP,20);assertEquals(2,s.expire(10_000_000).entries().size());assertThrows(IllegalStateException.class,s::clearTimed);}
 @Test public void startingMaintainDoesNotRecoverAlreadyExpiredRows(){HistoryStore.Snapshot s=visit(empty(),1,1,TEMP,1).withMaintaining(true,1+HistoryStore.RETENTION_MS);assertEquals(0,s.entries().size());}
 @Test public void endingMaintainRestartsFullTtlOnlyForTimedSources(){HistoryStore.Snapshot s=visit(visit(empty(),1,1,TEMP,1),2,2,SECOND,2).withMaintaining(true,3).withMaintaining(false,99_999_999);for(HistoryStore.Entry e:s.entries())if(e.workspaceId().equals(id("ws_",1)))assertEquals(Long.valueOf(99_999_999+HistoryStore.RETENTION_MS),e.expiresUtcMs());else assertNull(e.expiresUtcMs());}
 @Test public void clearTimedIncludesTemporaryAndShelvedButNotOpenDurable(){HistoryStore.Snapshot s=visit(visit(visit(empty(),1,1,TEMP,1),2,2,SECOND,2),3,3,PRIMARY,3).workspaceChanged(source(2,SECOND,false),10).clearTimed();assertEquals(1,s.entries().size());assertEquals(id("ws_",3),s.entries().get(0).workspaceId());}
 @Test public void missingDurableStartupSourceGetsDeadlineOnceNotEveryRestart(){HistoryStore.Snapshot s=visit(empty(),1,1,SECOND,1).reconcileSources(Collections.emptyList(),20);assertEquals(Long.valueOf(20+HistoryStore.RETENTION_MS),s.entries().get(0).expiresUtcMs());assertEquals(s.entries().get(0).expiresUtcMs(),s.reconcileSources(Collections.emptyList(),200).entries().get(0).expiresUtcMs());}
 @Test public void startupOnlyActualOpenDurableSourcesLoseTheirDeadline(){HistoryStore.Snapshot s=visit(visit(empty(),1,1,TEMP,1),2,2,TEMP,2).reconcileSources(Arrays.asList(source(1,SECOND,true),source(2,SECOND,false)),10);assertEquals(Long.valueOf(2+HistoryStore.RETENTION_MS),s.entries().get(0).expiresUtcMs());assertNull(s.entries().get(1).expiresUtcMs());}
 @Test public void historyDuplicatesRemainButRecentIsEightDistinctFullUrls(){HistoryStore.Snapshot s=empty();for(int i=1;i<=12;i++)s=s.addObservedVisit(page(1,i,TEMP,"https://example.test/?n="+(i%10)),i);assertEquals(12,s.entries().size());List<HistoryStore.Entry> recent=s.recentEntries(13);assertEquals(8,recent.size());assertEquals("https://example.test/?n=2",recent.get(0).url());Set<String> urls=new HashSet<>();for(HistoryStore.Entry e:recent)assertTrue(urls.add(e.url()));}
 @Test public void latestVisitWinsTimestampTieAndTitleUpdateDoesNotAddVisit(){HistoryStore.Snapshot s=visit(visit(empty(),1,1,TEMP,10),1,2,TEMP,10);assertEquals(id("tab_",2),s.entries().get(0).tabId());HistoryStore.Entry e=s.entries().get(0);assertSame(s,s.updateTitle(e.id(),"https://example.test/other","wrong"));assertEquals(2,s.updateTitle(e.id(),e.url(),"新标题").entries().size());}
 @Test public void maintenanceRoundTripsButProcessPauseDoesNotEnterWire(){HistoryStore.Snapshot s=visit(empty(),1,1,TEMP,1).withMaintaining(true,2);byte[] before=HistoryStore.CODEC.encode(s);HistoryStore.RecordingSession process=new HistoryStore.RecordingSession();process.setPaused(true);assertArrayEquals(before,HistoryStore.CODEC.encode(s));assertTrue(HistoryStore.CODEC.decode(ByteBuffer.wrap(before)).maintaining());assertFalse(new HistoryStore.RecordingSession().paused());}
 @Test public void recordingSwitchSurvivesWindowLikeReuseAndResumeIsOnlyForRealTransition(){HistoryStore.RecordingSession process=new HistoryStore.RecordingSession();assertTrue(process.setPaused(true).changed());assertTrue(process.paused());assertFalse(process.setPaused(true).needsCurrentPageSync());assertTrue(process.setPaused(false).needsCurrentPageSync());assertFalse(process.setPaused(false).needsCurrentPageSync());}
 @Test public void codecRejectsEveryTruncationTailOldMagicAndDuplicateOrdinal(){byte[] bytes=HistoryStore.CODEC.encode(visit(empty(),1,1,TEMP,1));for(int n=0;n<bytes.length;n++){byte[] cut=Arrays.copyOf(bytes,n);assertThrows(IllegalArgumentException.class,()->HistoryStore.CODEC.decode(ByteBuffer.wrap(cut)));}assertThrows(IllegalArgumentException.class,()->HistoryStore.CODEC.decode(ByteBuffer.wrap(Arrays.copyOf(bytes,bytes.length+1))));byte[] old=bytes.clone();old[7]='1';assertThrows(IllegalArgumentException.class,()->HistoryStore.CODEC.decode(ByteBuffer.wrap(old)));HistoryStore.Entry e=visit(empty(),1,1,TEMP,1).entries().get(0);HistoryStore.Entry duplicate=new HistoryStore.Entry(id("hv_",999),e.workspaceId(),e.tabId(),e.sourceTitle(),e.title(),e.url(),e.visitedUtcMs(),e.expiresUtcMs(),e.ordinal());assertThrows(IllegalArgumentException.class,()->new HistoryStore.Snapshot(0,false,Arrays.asList(e,duplicate)));}
 @Test public void invalidScopeClosedPageAndTimeOverflowFailWithoutInventedRecord(){assertThrows(IllegalArgumentException.class,()->new HistoryStore.Source("wrong","x",TEMP,true));assertThrows(IllegalArgumentException.class,()->new HistoryStore.Page(source(1,SECOND,false),id("tab_",1),"x","https://example.test/"));assertThrows(IllegalArgumentException.class,()->visit(empty(),1,1,TEMP,Long.MAX_VALUE));assertThrows(IllegalArgumentException.class,()->visit(new HistoryStore.Snapshot(Long.MAX_VALUE,false,Collections.emptyList()),1,1,TEMP,1));}
}
